    new: Any | None = Field(
        default=None,
        description="Incoming value the field will be set to after the upgrade (string, number, boolean, or `null`).",
    )
    old: Any | None = Field(
        default=None,
        description="Current value of the field before the upgrade (string, number, boolean, or `null`).",
    )


